		if (operator is ComparisonEq) {
			return left.value == right.value
					? Satisfiability.SATISFIED
					: Satisfiability.NOT_SATISFIED;
		}
		if (operator is ComparisonNe) {
			return left.value != right.value
					? Satisfiability.SATISFIED
					: Satisfiability.NOT_SATISFIED;
		}
		if (operator is ComparisonLe) {
			return left.value <= right.value
					? Satisfiability.SATISFIED
					: Satisfiability.NOT_SATISFIED;
